import { words, groupBy } from 'es-toolkit';
import { isEmpty } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function tokens(text: string): string[] {
  return words(text);
}

export function byAge(rows: Row[]): Record<string, Row[]> {
  return groupBy(rows, (row) => row.age);
}

export function isBlank(value: unknown): boolean {
  return isEmpty(value);
}
EOF
npm run size -- src/module.ts 2>&1 | tail -1; npm run size -- out/module.ts 2>&1 | tail -1
cat > out/t.mjs <<'EOF'
import w from 'lodash/words.js';
import { words } from 'es-toolkit';
const cs='aAbBZz09 -_.';let bad=0;
for(let i=0;i<200000;i++){let n=Math.random()*12|0,s='';while(n--)s+=cs[Math.random()*cs.length|0];
 if(JSON.stringify(w(s))!==JSON.stringify(words(s))){if(bad++<5)console.log(JSON.stringify(s),w(s),words(s));}}
console.log('bad',bad);
EOF
cp out/t.mjs ./t.mjs && node t.mjs; rm t.mjs out/t.mjs; npx tsc --noEmit -p . 2>&1 | head

